#include <iostream>
#include <vector>
using namespace std;
​
// 定义一个点结构体
struct Point {
    int x, y;
};
​
// 判断两个点是否相等
bool arePointsEqual(Point a, Point b) {
    return a.x == b.x && a.y == b.y;
}
​
// 检查数组中是否存在某点
bool pointExists(vector<Point>& points, Point p) {
    for (auto& point : points) {
        if (arePointsEqual(point, p)) {
            return true;
        }
    }
    return false;
}
​
int main() {
    int n;
    cin >> n;
​
    vector<Point> points(n);
​
    // 读取坐标并存入数组
    for (int i = 0; i < n; i++) {
        cin >> points[i].x >> points[i].y;
    }
​
    int squareCount = 0;
​
    // 遍历所有点对，检查是否能构成正方形
    for (int i = 0; i < n; i++) {
        int x1 = points[i].x;
        int y1 = points[i].y;
​
        for (int j = i + 1; j < n; j++) {
            int x2 = points[j].x;
            int y2 = points[j].y;
​
            // 计算两个可能的对角点
            Point p3 = {x1 - (y1 - y2), y1 + (x1 - x2)};
            Point p4 = {x2 - (y1 - y2), y2 + (x1 - x2)};
​
            if (pointExists(points, p3) && pointExists(points, p4)) {
                squareCount++;
            }
​
            // 计算另外两个可能的对角点
            Point p5 = {x1 + (y1 - y2), y1 - (x1 - x2)};
            Point p6 = {x2 + (y1 - y2), y2 - (x1 - x2)};
​
            if (pointExists(points, p5) && pointExists(points, p6)) {
                squareCount++;
            }
        }
    }
​
    // 每个正方形被计算了4次，因此结果需要除以4
    cout << squareCount / 4 << endl;
​
    return 0;
}

